</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ─────────────────────────────────────────────────────────────
// plane border (x7)      → LineSegments  square 4x4 in XZ at y=0,2,...,12  #444444
// plane border thick     → 3 offset LineSegments copies, visible only when layer active  #000000
// plane grid (x7)        → LineSegments  3x3 interior subdivision  #CCCCCC
// datapoints (x7 planes) → THREE.Points  120 verts, per-vertex color red/blue, size 5.5px
// trajectories           → 12 LineSegments groups (class x segment) built as explicit dash pieces
// envelope hull          → LineSegments  dashed  #AAAAAA opacity 0.3
// legend arrows (x6)     → Line shaft + ConeGeometry head, black, at (x=-3.2,z=3.2)
// legend labels (x6)     → addLabel rounded monospace boxes: linear/relu/linear/relu/linear/softmax
// iteration axis         → Line along (1,0,-1) at y=-1.65 + ConeGeometry head + tick LineSegments
// iteration marker       → ConeGeometry pointing down, slides along the axis with t
// ellipses / axis text   → addLabel
// ─────────────────────────────────────────────────────────────────────────────

const NPTS = 120;
const NL = 7;
const PLANE_Y = [0, 2, 4, 6, 8, 10, 12];
const HALF = 2;                       // plane half-size (4x4 square)
const RELU_LAYERS = { 2: true, 4: true };
const LAYER_NAMES = ['input', 'linear 1', 'relu 1', 'linear 2', 'relu 2', 'linear 3', 'softmax'];
const RED = 0xff1010, BLUE = 0x0b0bff;

/* ── deterministic RNG ─────────────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(20240917);
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

/* ── dataset: dense intermingled Gaussian cluster, class by polar checkerboard ── */
const baseX = new Float32Array(NPTS), baseZ = new Float32Array(NPTS);
const cls = new Uint8Array(NPTS);           // 0 = red, 1 = blue
const spread = new Float32Array(NPTS);      // blue outward gain
const zspread = new Float32Array(NPTS);
const jit = [];                             // jit[L][2i],[2i+1]
for (let L = 0; L < NL; L++) jit.push(new Float32Array(NPTS * 2));

for (let i = 0; i < NPTS; i++) {
  const x = gauss() * 0.35, z = gauss() * 0.35;
  baseX[i] = x; baseZ[i] = z;
  const ang = Math.atan2(z, x) + Math.PI;
  const r = Math.hypot(x, z);
  cls[i] = (Math.floor(ang / (Math.PI / 3)) + Math.floor(r / 0.16)) % 2;
  spread[i] = 0.25 + 0.8 * rng();
  zspread[i] = rng() * 2 - 1;
  for (let L = 0; L < NL; L++) {
    jit[L][2 * i] = gauss() * 0.07;
    jit[L][2 * i + 1] = gauss() * 0.07;
  }
}

/* ── per-layer fixed "linear" transforms ──────────────────────────────────── */
const ROT = [0, 0.14, -0.20, 0.17, -0.12, 0.22, -0.15];
const SCL = [1, 1.16, 1.00, 1.12, 1.00, 1.08, 0.96];

// P[L] = Float32Array(NPTS*2) of (x,z) on plane L
const P = [];
for (let L = 0; L < NL; L++) P.push(new Float32Array(NPTS * 2));

function computePositions(t) {
  const tn = Math.max(0, Math.min(1, t / 3));
  for (let i = 0; i < NPTS; i++) { P[0][2 * i] = baseX[i]; P[0][2 * i + 1] = baseZ[i]; }

  for (let L = 1; L < NL; L++) {
    const ca = Math.cos(ROT[L]) * SCL[L], sa = Math.sin(ROT[L]) * SCL[L];
    const contract = 1 - 0.45 * tn;
    const pull = 0.22 * tn;
    const push = 0.95 * tn;
    for (let i = 0; i < NPTS; i++) {
      let x = P[L - 1][2 * i], z = P[L - 1][2 * i + 1];
      let nx = ca * x - sa * z;
      let nz = sa * x + ca * z;
      nx += jit[L][2 * i]; nz += jit[L][2 * i + 1];
      if (cls[i] === 0) {                       // red: contract toward centre-left
        nx = nx * contract - pull;
        nz = nz * contract;
        nx += jit[L][2 * i] * 0.5 * tn;
        nz += jit[L][2 * i + 1] * 0.5 * tn;
      } else {                                  // blue: translate outward along +X
        nx += push * spread[i];
        nz += 0.22 * tn * zspread[i];
      }
      P[L][2 * i] = nx; P[L][2 * i + 1] = nz;
    }
    if (RELU_LAYERS[L]) {                       // relu: fold negatives against the axes
      for (let i = 0; i < NPTS; i++) {
        if (P[L][2 * i] < 0) P[L][2 * i] *= 0.10;
        if (P[L][2 * i + 1] < 0) P[L][2 * i + 1] *= 0.10;
      }
      let mx = 0, mz = 0, n = 0;
      for (let i = 0; i < NPTS; i++) if (cls[i] === 0) { mx += P[L][2 * i]; mz += P[L][2 * i + 1]; n++; }
      if (n) { mx = 0.8 * mx / n; mz = 0.8 * mz / n; }
      for (let i = 0; i < NPTS; i++) { P[L][2 * i] -= mx; P[L][2 * i + 1] -= mz; }
    }
    for (let i = 0; i < NPTS; i++) {            // safety clamp
      P[L][2 * i] = Math.max(-8, Math.min(8, P[L][2 * i]));
      P[L][2 * i + 1] = Math.max(-8, Math.min(8, P[L][2 * i + 1]));
    }
  }
}

/* ── planes: border + thick highlight + interior grid ─────────────────────── */
const planeBorders = [], planeThick = [], planeGrids = [];
for (let L = 0; L < NL; L++) {
  const y = PLANE_Y[L];
  const c = [[-HALF, -HALF], [HALF, -HALF], [HALF, HALF], [-HALF, HALF]];
  const bp = [];
  for (let k = 0; k < 4; k++) {
    const a = c[k], b = c[(k + 1) % 4];
    bp.push(a[0], y, a[1], b[0], y, b[1]);
  }
  const bg = new THREE.BufferGeometry();
  bg.setAttribute('position', new THREE.Float32BufferAttribute(bp, 3));
  const bm = new THREE.LineBasicMaterial({ color: 0x444444, transparent: true, opacity: 0.9 });
  const border = new THREE.LineSegments(bg, bm);
  scene.add(border); planeBorders.push(border);

  const thickGroup = new THREE.Group();
  const tm = new THREE.LineBasicMaterial({ color: 0x000000 });
  for (const off of [[0.012, 0, 0], [-0.012, 0, 0], [0, 0.012, 0], [0, -0.012, 0]]) {
    const l = new THREE.LineSegments(bg, tm);
    l.position.set(off[0], off[1], off[2]);
    thickGroup.add(l);
  }
  thickGroup.visible = false;
  scene.add(thickGroup); planeThick.push(thickGroup);

  const gp = [];
  for (let k = 1; k < 3; k++) {
    const v = -HALF + (2 * HALF) * k / 3;
    gp.push(v, y, -HALF, v, y, HALF);
    gp.push(-HALF, y, v, HALF, y, v);
  }
  const gg = new THREE.BufferGeometry();
  gg.setAttribute('position', new THREE.Float32BufferAttribute(gp, 3));
  const gm = new THREE.LineBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.85 });
  const grid = new THREE.LineSegments(gg, gm);
  scene.add(grid); planeGrids.push(grid);
}

/* ── point clouds (one THREE.Points per plane, per-vertex colour) ─────────── */
const pointObjs = [];
for (let L = 0; L < NL; L++) {
  const g = new THREE.BufferGeometry();
  const pos = new Float32Array(NPTS * 3);
  const col = new Float32Array(NPTS * 3);
  for (let i = 0; i < NPTS; i++) {
    const c = new THREE.Color(cls[i] ? BLUE : RED);
    col[3 * i] = c.r; col[3 * i + 1] = c.g; col[3 * i + 2] = c.b;
  }
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  const m = new THREE.PointsMaterial({
    size: 5.5, sizeAttenuation: false, vertexColors: true,
    transparent: true, opacity: 1, depthWrite: false
  });
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false;
  scene.add(pts);
  pointObjs.push(pts);
}

/* ── dashed-geometry helper (explicit dash pieces → batched LineSegments) ─── */
function makeTarget(capacityFloats, color, opacity) {
  const arr = new Float32Array(capacityFloats);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  g.setDrawRange(0, 0);
  const m = new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
  const o = new THREE.LineSegments(g, m);
  o.frustumCulled = false;
  scene.add(o);
  return { arr, geom: g, obj: o, mat: m, n: 0 };
}
function resetTarget(T) { T.n = 0; }
function commitTarget(T) {
  T.geom.attributes.position.needsUpdate = true;
  T.geom.setDrawRange(0, T.n / 3);
}
const _a = new THREE.Vector3(), _b = new THREE.Vector3();
function addDashedPolyline(T, pts, dash, gap) {
  let drawing = true, remaining = dash;
  for (let k = 0; k + 1 < pts.length; k++) {
    const a = pts[k], b = pts[k + 1];
    const segLen = a.distanceTo(b);
    if (segLen < 1e-9) continue;
    let travelled = 0;
    while (travelled < segLen - 1e-9) {
      const step = Math.min(remaining, segLen - travelled);
      if (drawing && T.n + 6 <= T.arr.length) {
        const t0 = travelled / segLen, t1 = (travelled + step) / segLen;
        _a.lerpVectors(a, b, t0); _b.lerpVectors(a, b, t1);
        T.arr[T.n++] = _a.x; T.arr[T.n++] = _a.y; T.arr[T.n++] = _a.z;
        T.arr[T.n++] = _b.x; T.arr[T.n++] = _b.y; T.arr[T.n++] = _b.z;
      }
      travelled += step; remaining -= step;
      if (remaining <= 1e-9) { drawing = !drawing; remaining = drawing ? dash : gap; }
    }
  }
}

/* ── trajectory groups: [class][segment] ──────────────────────────────────── */
const CAP = 60 * 260;
const traj = [[], []];
for (let c = 0; c < 2; c++)
  for (let s = 0; s < 6; s++)
    traj[c].push(makeTarget(CAP, c ? BLUE : RED, 0.35));

const envelope = makeTarget(20000, 0xaaaaaa, 0.3);
const hilite = makeTarget(4000, 0x111111, 1.0);
hilite.mat.color.set(0x000000);

/* hovered-datapoint enlarged dots */
const hiliteDotsGeom = new THREE.BufferGeometry();
hiliteDotsGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(NL * 3), 3));
const hiliteDotsMat = new THREE.PointsMaterial({ size: 11, sizeAttenuation: false, color: 0x000000, transparent: true, opacity: 1, depthWrite: false });
const hiliteDots = new THREE.Points(hiliteDotsGeom, hiliteDotsMat);
hiliteDots.frustumCulled = false;
hiliteDots.visible = false;
scene.add(hiliteDots);

/* ── curve sampling ───────────────────────────────────────────────────────── */
const SUB = 8;
function curveSamples(i) {
  const knots = [];
  for (let L = 0; L < NL; L++) knots.push(new THREE.Vector3(P[L][2 * i], PLANE_Y[L], P[L][2 * i + 1]));
  const curve = new THREE.CatmullRomCurve3(knots, false, 'catmullrom', 0.35);
  return curve.getPoints((NL - 1) * SUB);
}

/* ── full geometry rebuild for the current iteration value ────────────────── */
let hoverIdx = -1;

function rebuild(t) {
  computePositions(t);

  for (let L = 0; L < NL; L++) {
    const arr = pointObjs[L].geometry.attributes.position.array;
    for (let i = 0; i < NPTS; i++) {
      arr[3 * i] = P[L][2 * i];
      arr[3 * i + 1] = PLANE_Y[L];
      arr[3 * i + 2] = P[L][2 * i + 1];
    }
    pointObjs[L].geometry.attributes.position.needsUpdate = true;
  }

  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) resetTarget(traj[c][s]);
  for (let i = 0; i < NPTS; i++) {
    const sm = curveSamples(i);
    for (let s = 0; s < 6; s++) {
      addDashedPolyline(traj[cls[i]][s], sm.slice(s * SUB, s * SUB + SUB + 1), 0.13, 0.11);
    }
  }
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) commitTarget(traj[c][s]);

  // gray envelope: extreme points of each cloud, linked plane to plane
  resetTarget(envelope);
  const ext = [];
  for (let L = 0; L < NL; L++) {
    let ixMin = 0, ixMax = 0, izMin = 0, izMax = 0;
    for (let i = 1; i < NPTS; i++) {
      if (P[L][2 * i] < P[L][2 * ixMin]) ixMin = i;
      if (P[L][2 * i] > P[L][2 * ixMax]) ixMax = i;
      if (P[L][2 * i + 1] < P[L][2 * izMin + 1]) izMin = i;
      if (P[L][2 * i + 1] > P[L][2 * izMax + 1]) izMax = i;
    }
    const idx = [ixMax, izMax, ixMin, izMin];
    ext.push(idx.map(i => new THREE.Vector3(P[L][2 * i], PLANE_Y[L], P[L][2 * i + 1])));
  }
  for (let L = 0; L < NL; L++) {
    for (let k = 0; k < 4; k++) addDashedPolyline(envelope, [ext[L][k], ext[L][(k + 1) % 4]], 0.12, 0.12);
    if (L + 1 < NL) for (let k = 0; k < 4; k++) addDashedPolyline(envelope, [ext[L][k], ext[L + 1][k]], 0.14, 0.12);
  }
  commitTarget(envelope);

  refreshHighlight();
}

function refreshHighlight() {
  resetTarget(hilite);
  if (hoverIdx < 0) {
    commitTarget(hilite);
    hiliteDots.visible = false;
    return;
  }
  const sm = curveSamples(hoverIdx);
  addDashedPolyline(hilite, sm, 0.16, 0.08);
  commitTarget(hilite);
  hilite.mat.color.set(cls[hoverIdx] ? BLUE : RED);
  const arr = hiliteDotsGeom.attributes.position.array;
  for (let L = 0; L < NL; L++) {
    arr[3 * L] = P[L][2 * hoverIdx];
    arr[3 * L + 1] = PLANE_Y[L];
    arr[3 * L + 2] = P[L][2 * hoverIdx + 1];
  }
  hiliteDotsGeom.attributes.position.needsUpdate = true;
  hiliteDotsMat.color.set(cls[hoverIdx] ? BLUE : RED);
  hiliteDots.visible = true;
}

/* ── legend column (arrows + boxed monospace labels) ──────────────────────── */
const LX = -3.2, LZ = 3.2;
const LEGEND = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
for (let k = 0; k < 6; k++) {
  const y0 = PLANE_Y[k] + 0.15, y1 = PLANE_Y[k] + 0.95;
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(LX, y0, LZ), new THREE.Vector3(LX, y1, LZ)
  ]);
  scene.add(new THREE.Line(g, blackLine));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.26, 12), blackMat);
  head.position.set(LX, y1 + 0.13, LZ);
  scene.add(head);
}

/* ── training-iteration axis ──────────────────────────────────────────────── */
const AXIS_Y = -1.7;
const axisDir = new THREE.Vector3(1, 0, -1).normalize();
const axisStart = new THREE.Vector3(-3.6, AXIS_Y, 3.6);
const AXIS_LEN = 9.2;
function ptAlong(f) { return axisStart.clone().addScaledVector(axisDir, f * AXIS_LEN); }
const axisBreaks = [[0.0, 0.42], [0.50, 0.68], [0.76, 1.0]];
for (const [f0, f1] of axisBreaks) {
  const g = new THREE.BufferGeometry().setFromPoints([ptAlong(f0), ptAlong(f1)]);
  scene.add(new THREE.Line(g, blackLine));
}
const axisHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.3, 12), blackMat);
axisHead.position.copy(ptAlong(1.0)).addScaledVector(axisDir, 0.14);
axisHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axisDir);
scene.add(axisHead);

const TICK_F = [0.06, 0.30, 0.60, 0.94];
const tickPts = [];
for (const f of TICK_F) {
  const p = ptAlong(f);
  tickPts.push(p.clone().setY(AXIS_Y - 0.12), p.clone().setY(AXIS_Y + 0.12));
}
const tickGeom = new THREE.BufferGeometry().setFromPoints(tickPts);
scene.add(new THREE.LineSegments(tickGeom, new THREE.LineBasicMaterial({ color: 0x777777 })));

const marker = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.3, 14),
  new THREE.MeshBasicMaterial({ color: 0x1565c0 }));
marker.rotation.z = Math.PI;
scene.add(marker);
function placeMarker(t) {
  const f = TICK_F[0] + (TICK_F[3] - TICK_F[0]) * (t / 3);
  const p = ptAlong(f);
  marker.position.set(p.x, AXIS_Y + 0.34, p.z);
  markerLabel.pos.set(p.x, AXIS_Y + 0.95, p.z);
}

/* ── build once, then frame the camera ────────────────────────────────────── */
rebuild(0);
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});
controls.minPolarAngle = THREE.MathUtils.degToRad(25);
controls.maxPolarAngle = THREE.MathUtils.degToRad(88);
controls.minAzimuthAngle = THREE.MathUtils.degToRad(45 - 55);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(45 + 55);

/* ── labels ───────────────────────────────────────────────────────────────── */
const boxCSS = 'display:inline-block;border:1px solid #222;border-radius:7px;padding:1px 7px;' +
  'background:#fff;font-family:ui-monospace,Consolas,monospace;font-size:12px;color:#111;';
for (let k = 0; k < 6; k++) {
  addLabel(`<span style="${boxCSS}">${LEGEND[k]}</span>`,
    new THREE.Vector3(LX, PLANE_Y[k] + 1.45, LZ));
}
addLabel('Training iteration', ptAlong(0.05), { offset: [0, -20], fontSize: '13px' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', ptAlong(0.46), { fontSize: '15px', color: '#111' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', ptAlong(0.72), { fontSize: '15px', color: '#111' });
const markerLabel = addLabel('iteration 0', new THREE.Vector3(0, 0, 0),
  { fontSize: '11px', color: '#1565c0', bold: true });
placeMarker(0);

/* ── state + highlight logic ──────────────────────────────────────────────── */
let targetT = 0, displayT = 0, activeLayer = 0;

function applyLayerHighlight() {
  const A = activeLayer;
  const showAll = (A === 0);
  for (let L = 0; L < NL; L++) {
    const faded = !showAll && L > A;
    planeBorders[L].material.color.set(L === A ? 0x000000 : 0x444444);
    planeBorders[L].material.opacity = faded ? 0.25 : 0.9;
    planeThick[L].visible = (L === A);
    planeGrids[L].material.opacity = faded ? 0.18 : 0.85;
    let po;
    if (showAll) po = 1;
    else if (L === A || L === A - 1) po = 1;
    else if (L > A) po = 0.15;
    else po = 0.4;
    pointObjs[L].material.opacity = po;
  }
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) {
    traj[c][s].mat.opacity = showAll ? 0.35 : (s === A - 1 ? 0.9 : 0.07);
  }
  envelope.mat.opacity = showAll ? 0.3 : 0.12;
}

function setIteration(t, fromSlider) {
  targetT = t;
  const names = ['initialization', 'early training', 'mid training', 'late training'];
  document.getElementById('iterReadout').innerHTML =
    `iteration ${t} / 3 &nbsp;(${names[t]})`;
  if (!fromSlider) document.getElementById('iterSlider').value = String(t);
}

function setLayer(idx) {
  activeLayer = idx;
  [...layerBtns.children].forEach((b, i) => b.classList.toggle('active', i === idx));
  applyLayerHighlight();
}

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const layerBtns = document.getElementById('layerBtns');
LAYER_NAMES.forEach((n, i) => {
  const b = document.createElement('button');
  b.textContent = n;
  b.style.fontFamily = 'ui-monospace,Consolas,monospace';
  b.style.fontSize = '11px';
  b.addEventListener('click', () => setLayer(i));
  layerBtns.appendChild(b);
});

const slider = document.getElementById('iterSlider');
slider.addEventListener('input', () => setIteration(parseInt(slider.value, 10), true));

const STEPS = [
  { title: 'Initialization: classes intermingled', narr: 'At iteration 0 the red and blue points stay mixed all the way up the stack; even the softmax plane shows the two colors overlapping.', t: 0, layer: 6 },
  { title: 'Start at the input plane', narr: 'The bottom plane holds the raw data: one dense central cluster with red and blue thoroughly intermingled.', t: 0, layer: 0 },
  { title: 'First linear + relu', narr: 'The first linear layer stretches and rotates the cloud, then relu folds everything lying past the axes back toward them, producing the first hint of structure.', t: 2, layer: 2 },
  { title: 'Deeper layers pull the classes apart', narr: 'By the second relu the red points have begun collecting into a narrow column while blue points bow outward to one side.', t: 2, layer: 4 },
  { title: 'Late training, full forward pass', narr: 'At the final iteration the softmax plane shows a tight red bundle and blue points flung far to the opposite side — a clean, confident separation.', t: 3, layer: 6 }
];
let stepIdx = -1;
function goToStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setIteration(s.t, false);
  setLayer(s.layer);
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length}  ${s.title}`;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));

setLayer(0);
setIteration(0, false);

/* ── hover: trace one datapoint through the network ───────────────────────── */
const myRay = new THREE.Raycaster();
myRay.params.Points.threshold = 0.11;
const myPointer = new THREE.Vector2();

function pickIndex(event) {
  const rect = canvas.getBoundingClientRect();
  myPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  myPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  myRay.setFromCamera(myPointer, camera);
  const hits = myRay.intersectObjects(pointObjs, false);
  return hits.length ? hits[0].index : -1;
}
function pointInfo(i) {
  const c = cls[i] ? 'blue' : 'red';
  const f = (L) => `(${P[L][2 * i].toFixed(2)}, ${P[L][2 * i + 1].toFixed(2)})`;
  return `${c} datapoint #${i} · input ${f(0)} → relu1 ${f(2)} → relu2 ${f(4)} → softmax ${f(6)}`;
}
canvas.addEventListener('pointermove', (e) => {
