function rebuild(t) {
  computePositions(t);

  for (let L = 0; L < NL; L++) {
    const arr = pointObjs[L].geometry.attributes.position.array;
    for (let i = 0; i < NPTS; i++) {
      arr[3 * i] = P[L][2 * i];
      arr[3 * i + 1] = PLANE_Y[L];
      arr[3 * i + 2] = P[L][2 * i + 1];
    }
    pointObjs[L].geometry.attributes.position.needsUpdate = true;
  }

  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) resetTarget(traj[c][s]);
  for (let i = 0; i < NPTS; i++) {
    const sm = curveSamples(i);
    for (let s = 0; s < 6; s++) {
      addDashedPolyline(traj[cls[i]][s], sm.slice(s * SUB, s * SUB + SUB + 1), 0.13, 0.11);
    }
  }
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) commitTarget(traj[c][s]);

  // gray envelope: extreme points of each cloud, linked plane to plane
  resetTarget(envelope);
  const ext = [];
  for (let L = 0; L < NL; L++) {
    let ixMin = 0, ixMax = 0, izMin = 0, izMax = 0;
    for (let i = 1; i < NPTS; i++) {
      if (P[L][2 * i] < P[L][2 * ixMin]) ixMin = i;
      if (P[L][2 * i] > P[L][2 * ixMax]) ixMax = i;
      if (P[L][2 * i + 1] < P[L][2 * izMin + 1]) izMin = i;
      if (P[L][2 * i + 1] > P[L][2 * izMax + 1]) izMax = i;
    }
    const idx = [ixMax, izMax, ixMin, izMin];
    ext.push(idx.map(i => new THREE.Vector3(P[L][2 * i], PLANE_Y[L], P[L][2 * i + 1])));
  }
  for (let L = 0; L < NL; L++) {
    for (let k = 0; k < 4; k++) addDashedPolyline(envelope, [ext[L][k], ext[L][(k + 1) % 4]], 0.12, 0.12);
    if (L + 1 < NL) for (let k = 0; k < 4; k++) addDashedPolyline(envelope, [ext[L][k], ext[L + 1][k]], 0.14, 0.12);
  }
  commitTarget(envelope);

  refreshHighlight();
}

function refreshHighlight() {
  resetTarget(hilite);
  if (hoverIdx < 0) {
    commitTarget(hilite);
    hiliteDots.visible = false;
    return;
  }
  const sm = curveSamples(hoverIdx);
  addDashedPolyline(hilite, sm, 0.16, 0.08);
  commitTarget(hilite);
  hilite.mat.color.set(cls[hoverIdx] ? BLUE : RED);
  const arr = hiliteDotsGeom.attributes.position.array;
  for (let L = 0; L < NL; L++) {
    arr[3 * L] = P[L][2 * hoverIdx];
    arr[3 * L + 1] = PLANE_Y[L];
    arr[3 * L + 2] = P[L][2 * hoverIdx + 1];
  }
  hiliteDotsGeom.attributes.position.needsUpdate = true;
  hiliteDotsMat.color.set(cls[hoverIdx] ? BLUE : RED);
  hiliteDots.visible = true;
}

/* ── legend column (arrows + boxed monospace labels) ──────────────────────── */
const LX = -3.2, LZ = 3.2;
const LEGEND = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
for (let k = 0; k < 6; k++) {
  const y0 = PLANE_Y[k] + 0.15, y1 = PLANE_Y[k] + 0.95;
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(LX, y0, LZ), new THREE.Vector3(LX, y1, LZ)
  ]);
  scene.add(new THREE.Line(g, blackLine));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.26, 12), blackMat);
  head.position.set(LX, y1 + 0.13, LZ);
  scene.add(head);
}

/* ── training-iteration axis ──────────────────────────────────────────────── */
const AXIS_Y = -1.7;
const axisDir = new THREE.Vector3(1, 0, -1).normalize();
const axisStart = new THREE.Vector3(-3.6, AXIS_Y, 3.6);
const AXIS_LEN = 9.2;
function ptAlong(f) { return axisStart.clone().addScaledVector(axisDir, f * AXIS_LEN); }
const axisBreaks = [[0.0, 0.42], [0.50, 0.68], [0.76, 1.0]];
for (const [f0, f1] of axisBreaks) {
  const g = new THREE.BufferGeometry().setFromPoints([ptAlong(f0), ptAlong(f1)]);
  scene.add(new THREE.Line(g, blackLine));
}
const axisHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.3, 12), blackMat);
axisHead.position.copy(ptAlong(1.0)).addScaledVector(axisDir, 0.14);
axisHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axisDir);
scene.add(axisHead);

const TICK_F = [0.06, 0.30, 0.60, 0.94];
const tickPts = [];
for (const f of TICK_F) {
  const p = ptAlong(f);
  tickPts.push(p.clone().setY(AXIS_Y - 0.12), p.clone().setY(AXIS_Y + 0.12));
}
const tickGeom = new THREE.BufferGeometry().setFromPoints(tickPts);
scene.add(new THREE.LineSegments(tickGeom, new THREE.LineBasicMaterial({ color: 0x777777 })));

const marker = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.3, 14),
  new THREE.MeshBasicMaterial({ color: 0x1565c0 }));
marker.rotation.z = Math.PI;
scene.add(marker);
function placeMarker(t) {
  const f = TICK_F[0] + (TICK_F[3] - TICK_F[0]) * (t / 3);
  const p = ptAlong(f);
  marker.position.set(p.x, AXIS_Y + 0.34, p.z);
  markerLabel.pos.set(p.x, AXIS_Y + 0.95, p.z);
}

/* ── build once, then frame the camera ────────────────────────────────────── */
rebuild(0);
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});
controls.minPolarAngle = THREE.MathUtils.degToRad(25);
controls.maxPolarAngle = THREE.MathUtils.degToRad(88);
controls.minAzimuthAngle = THREE.MathUtils.degToRad(45 - 55);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(45 + 55);

/* ── labels ───────────────────────────────────────────────────────────────── */
const boxCSS = 'display:inline-block;border:1px solid #222;border-radius:7px;padding:1px 7px;' +
  'background:#fff;font-family:ui-monospace,Consolas,monospace;font-size:12px;color:#111;';
for (let k = 0; k < 6; k++) {
  addLabel(`<span style="${boxCSS}">${LEGEND[k]}</span>`,
    new THREE.Vector3(LX, PLANE_Y[k] + 1.45, LZ));
}
addLabel('Training iteration', ptAlong(0.05), { offset: [0, -20], fontSize: '13px' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', ptAlong(0.46), { fontSize: '15px', color: '#111' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', ptAlong(0.72), { fontSize: '15px', color: '#111' });
const markerLabel = addLabel('iteration 0', new THREE.Vector3(0, 0, 0),
  { fontSize: '11px', color: '#1565c0', bold: true });
placeMarker(0);

/* ── state + highlight logic ──────────────────────────────────────────────── */
let targetT = 0, displayT = 0, activeLayer = 0;

function applyLayerHighlight() {
  const A = activeLayer;
  const showAll = (A === 0);
  for (let L = 0; L < NL; L++) {
    const faded = !showAll && L > A;
    planeBorders[L].material.color.set(L === A ? 0x000000 : 0x444444);
    planeBorders[L].material.opacity = faded ? 0.25 : 0.9;
    planeThick[L].visible = (L === A);
    planeGrids[L].material.opacity = faded ? 0.18 : 0.85;
    let po;
    if (showAll) po = 1;
    else if (L === A || L === A - 1) po = 1;
    else if (L > A) po = 0.15;
    else po = 0.4;
    pointObjs[L].material.opacity = po;
  }
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) {
    traj[c][s].mat.opacity = showAll ? 0.35 : (s === A - 1 ? 0.9 : 0.07);
  }
  envelope.mat.opacity = showAll ? 0.3 : 0.12;
}

function setIteration(t, fromSlider) {
  targetT = t;
  const names = ['initialization', 'early training', 'mid training', 'late training'];
  document.getElementById('iterReadout').innerHTML =
    `iteration ${t} / 3 &nbsp;(${names[t]})`;
  if (!fromSlider) document.getElementById('iterSlider').value = String(t);
}

function setLayer(idx) {
  activeLayer = idx;
  [...layerBtns.children].forEach((b, i) => b.classList.toggle('active', i === idx));
  applyLayerHighlight();
}

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const layerBtns = document.getElementById('layerBtns');
LAYER_NAMES.forEach((n, i) => {
  const b = document.createElement('button');
  b.textContent = n;
  b.style.fontFamily = 'ui-monospace,Consolas,monospace';
  b.style.fontSize = '11px';
  b.addEventListener('click', () => setLayer(i));
  layerBtns.appendChild(b);
});

const slider = document.getElementById('iterSlider');
slider.addEventListener('input', () => setIteration(parseInt(slider.value, 10), true));

const STEPS = [
  { title: 'Initialization: classes intermingled', narr: 'At iteration 0 the red and blue points stay mixed all the way up the stack; even the softmax plane shows the two colors overlapping.', t: 0, layer: 6 },
  { title: 'Start at the input plane', narr: 'The bottom plane holds the raw data: one dense central cluster with red and blue thoroughly intermingled.', t: 0, layer: 0 },
  { title: 'First linear + relu', narr: 'The first linear layer stretches and rotates the cloud, then relu folds everything lying past the axes back toward them, producing the first hint of structure.', t: 2, layer: 2 },
  { title: 'Deeper layers pull the classes apart', narr: 'By the second relu the red points have begun collecting into a narrow column while blue points bow outward to one side.', t: 2, layer: 4 },
  { title: 'Late training, full forward pass', narr: 'At the final iteration the softmax plane shows a tight red bundle and blue points flung far to the opposite side — a clean, confident separation.', t: 3, layer: 6 }
];
let stepIdx = -1;
function goToStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setIteration(s.t, false);
  setLayer(s.layer);
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length}  ${s.title}`;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));

setLayer(0);
setIteration(0, false);

/* ── hover: trace one datapoint through the network ───────────────────────── */
const myRay = new THREE.Raycaster();
myRay.params.Points.threshold = 0.11;
const myPointer = new THREE.Vector2();

function pickIndex(event) {
  const rect = canvas.getBoundingClientRect();
  myPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  myPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  myRay.setFromCamera(myPointer, camera);
  const hits = myRay.intersectObjects(pointObjs, false);
  return hits.length ? hits[0].index : -1;
}
function pointInfo(i) {
  const c = cls[i] ? 'blue' : 'red';
  const f = (L) => `(${P[L][2 * i].toFixed(2)}, ${P[L][2 * i + 1].toFixed(2)})`;
  return `${c} datapoint #${i} · input ${f(0)} → relu1 ${f(2)} → relu2 ${f(4)} → softmax ${f(6)}`;
}
canvas.addEventListener('pointermove', (e) => {
  const idx = pickIndex(e);
  if (idx !== hoverIdx) { hoverIdx = idx; refreshHighlight(); }
  if (idx >= 0) showTooltip(pointInfo(idx), e);
});
canvas.addEventListener('pointerleave', () => {
  if (hoverIdx !== -1) { hoverIdx = -1; refreshHighlight(); }
});
canvas.addEventListener('click', (e) => {
  const idx = pickIndex(e);
  if (idx < 0) return;
  showPopup(`${cls[idx] ? 'Blue' : 'Red'} datapoint #${idx}`,
    'This single datapoint keeps its identity through all seven activation planes. ' +
    'Its dashed trajectory shows where each linear, relu and softmax layer sends it. ' +
    pointInfo(idx));
});

/* ── smooth scrub between iteration keyframes ─────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  if (Math.abs(displayT - targetT) > 1e-3) {
    displayT += (targetT - displayT) * 0.14;
    if (Math.abs(displayT - targetT) <= 1e-3) displayT = targetT;
    rebuild(displayT);
    placeMarker(displayT);
    markerLabel.div.innerHTML = `iteration ${Math.round(displayT)}`;
  }
}
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
