<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC (one line per visible element) ──────────────────────────────
// root group           → THREE.Group, uniform scale 0.19 (keeps the wide 4-column figure in frustum)
// plane outline (7×4)  → LineSegments, 4×4 square in XZ at y = 0,4.5,…,27      #444444
// plane active outline → 4 pixel-offset LineSegments copies, black (active layer only)
// plane grid (7×4)     → LineSegments, interior 3×3 subdivision                #CCCCCC
// datapoints (7×4)     → THREE.Points, 120 verts, per-vertex red/blue, 5px
// trajectories         → LineSegments, explicit dash pieces, batched per (column, class, gap)
// envelope hull (×4)   → LineSegments dashed #AAAAAA, cloud extremes plane→plane
// legend arrows (×7)   → Line shaft + ConeGeometry head, black, far left of column 0
// legend labels (×6)   → addLabel boxed monospace: linear/relu/linear/relu/linear/softmax
// iteration axis       → 3 Line pieces along (1,0,-1) at y = -4 + ConeGeometry head
// ellipses (×2)        → addLabel  "· · ·"  on the axis breaks
// axis caption         → addLabel "Training iteration"
// iteration readout    → addLabel under the focused column
// ─────────────────────────────────────────────────────────────────────────────

const S = 0.19;                                  // global scale of the whole figure
const root = new THREE.Group();
root.scale.setScalar(S);
scene.add(root);

const NPTS = 120, NL = 7, NCOL = 4;
const GAP = 4.5;                                  // vertical spacing between planes
const PLANE_Y = [0, GAP, 2 * GAP, 3 * GAP, 4 * GAP, 5 * GAP, 6 * GAP];
const HALF = 2, SPACING = 10.5;
const U = new THREE.Vector3(1, 0, -1).normalize();   // pure screen-horizontal under iso pose
const RELU = { 2: 1, 4: 1 };
const RED = 0xff0000, BLUE = 0x0000ff;
const LAYER_NAMES = ['input', 'linear 1', 'relu 1', 'linear 2', 'relu 2', 'linear 3', 'softmax'];
const LEGEND = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
const AXIS_Y = -4.0, CAP_Y = -2.6, LEG_X = -7.5;
const AX_START = -6.0, AX_END = (NCOL - 1) * SPACING + 5.0;

function world(v) { return v.clone().multiplyScalar(S); }
function alongU(f, y) { return U.clone().multiplyScalar(f).setY(y); }

/* ── deterministic RNG ─────────────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(20240917);
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  const g = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  return Number.isFinite(g) ? g : 0;
}

/* ── dataset: one dense cluster, classes interleaved by a spiral checkerboard ─ */
const baseX = new Float32Array(NPTS), baseZ = new Float32Array(NPTS);
const cls = new Uint8Array(NPTS);
const spread = new Float32Array(NPTS);     // how far a blue point is flung outward
const zspread = new Float32Array(NPTS);
const jit = [];
for (let L = 0; L < NL; L++) jit.push(new Float32Array(NPTS * 2));
for (let i = 0; i < NPTS; i++) {
  const x = gauss() * 0.45, z = gauss() * 0.45;
  baseX[i] = x; baseZ[i] = z;
  const ang = Math.atan2(z, x) + Math.PI;
  const r = Math.hypot(x, z);
  cls[i] = (Math.floor(ang / (Math.PI / 3)) + Math.floor(r / 0.2)) % 2;
  spread[i] = 0.25 + 1.25 * rng();
  zspread[i] = rng() * 2 - 1;
  for (let L = 0; L < NL; L++) {
    jit[L][2 * i] = gauss() * 0.06;
    jit[L][2 * i + 1] = gauss() * 0.06;
  }
}

/* ── per-layer fixed transforms: funnel contraction + small rotation ───────── */
const CONTRACT = [1, 0.86, 0.82, 0.79, 0.76, 0.73, 0.70];
const ROT = [0, 0.17, -0.11, 0.21, -0.13, 0.24, -0.15];
const SCL = [1, 1.10, 1.00, 1.08, 1.00, 1.06, 0.98];

function fin(v) { return Number.isFinite(v) ? Math.max(-9, Math.min(9, v)) : 0; }

// t in [0,3]: 0 = initialization (classes statistically identical everywhere),
// 3 = late training (red collapses to a thread, blue is flung far along +X).
function computeStack(t) {
  const tn = Math.max(0, Math.min(1, t / 3));
  const P = [];
  for (let L = 0; L < NL; L++) P.push(new Float32Array(NPTS * 2));
  for (let i = 0; i < NPTS; i++) { P[0][2 * i] = baseX[i]; P[0][2 * i + 1] = baseZ[i]; }
  const redK = 1 - 0.44 * tn;                 // red contracts toward the plane centre
  const push = 1.25 * tn;                     // blue translates outward along +X
  for (let L = 1; L < NL; L++) {
    const c = CONTRACT[L] * SCL[L];
    const ca = Math.cos(ROT[L]) * c, sa = Math.sin(ROT[L]) * c;
    const jf = 1 - 0.5 * tn;
    for (let i = 0; i < NPTS; i++) {
      const x = P[L - 1][2 * i], z = P[L - 1][2 * i + 1];
      let nx = ca * x - sa * z, nz = sa * x + ca * z;
      if (cls[i] === 0) {                     // red
        nx = nx * redK - 0.03 * tn;
        nz = nz * redK;
      } else {                                // blue
        nx += push * spread[i];
        nz += 0.20 * tn * zspread[i];
      }
      nx += jit[L][2 * i] * jf;
      nz += jit[L][2 * i + 1] * jf;
      if (RELU[L]) {                          // relu folds negatives onto the axes
        if (nx < 0) nx *= 0.12;
        if (nz < 0) nz *= 0.12;
      }
      P[L][2 * i] = fin(nx); P[L][2 * i + 1] = fin(nz);
    }
  }
  return P;
}

/* ── dashed-polyline helper (explicit dash pieces → batched LineSegments) ─── */
const _da = new THREE.Vector3(), _db = new THREE.Vector3();
function pushDashes(out, pts, dash, gap) {
  let drawing = true, remaining = dash;
  for (let k = 0; k + 1 < pts.length; k++) {
    const a = pts[k], b = pts[k + 1];
    if (!Number.isFinite(a.x + a.y + a.z + b.x + b.y + b.z)) continue;
    const len = a.distanceTo(b);
    if (!(len > 1e-9)) continue;
    let tr = 0, guard = 0;
    while (tr < len - 1e-9 && guard++ < 4000) {
      const step = Math.min(remaining, len - tr);
      if (drawing) {
        _da.lerpVectors(a, b, tr / len);
        _db.lerpVectors(a, b, (tr + step) / len);
        out.push(_da.x, _da.y, _da.z, _db.x, _db.y, _db.z);
      }
      tr += step; remaining -= step;
      if (remaining <= 1e-9) { drawing = !drawing; remaining = drawing ? dash : gap; }
    }
  }
}
function segObj(parent, arr, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(arr.length ? arr : [0, 0, 0, 0, 0, 0], 3));
  const m = new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthWrite: false });
  const o = new THREE.LineSegments(g, m);
  o.frustumCulled = false;
  parent.add(o);
  return o;
}

/* ── smooth curve through a datapoint's 7 plane positions ─────────────────── */
const SUB = 8;
function curvePoints(P, i) {
  const knots = [];
  for (let L = 0; L < NL; L++) knots.push(new THREE.Vector3(P[L][2 * i], PLANE_Y[L], P[L][2 * i + 1]));
  return new THREE.CatmullRomCurve3(knots, false, 'catmullrom', 0.25).getPoints((NL - 1) * SUB);
}

/* ── build one training-iteration column ──────────────────────────────────── */
function buildColumn(k) {
  const P = computeStack(k);
  const g = new THREE.Group();
  g.position.copy(U).multiplyScalar(k * SPACING);
  root.add(g);

  const borders = [], thicks = [], grids = [], points = [];
  for (let L = 0; L < NL; L++) {
    const y = PLANE_Y[L];
    const corners = [[-HALF, -HALF], [HALF, -HALF], [HALF, HALF], [-HALF, HALF]];
    const bp = [];
    for (let c = 0; c < 4; c++) {
      const a = corners[c], b = corners[(c + 1) % 4];
      bp.push(a[0], y, a[1], b[0], y, b[1]);
    }
    const bgeo = new THREE.BufferGeometry();
    bgeo.setAttribute('position', new THREE.Float32BufferAttribute(bp, 3));
    const border = new THREE.LineSegments(bgeo,
      new THREE.LineBasicMaterial({ color: 0x444444, transparent: true, opacity: 0.92 }));
    g.add(border); borders.push(border);

    const th = new THREE.Group();
    const tmat = new THREE.LineBasicMaterial({ color: 0x000000 });
    [[0.07, 0], [-0.07, 0], [0, 0.07], [0, -0.07]].forEach(o => {
      const l = new THREE.LineSegments(bgeo, tmat);
      l.position.set(o[0], o[1], 0);
      th.add(l);
    });
    th.visible = false; g.add(th); thicks.push(th);

    const gp = [];
    for (let q = 1; q < 3; q++) {
      const v = -HALF + (2 * HALF) * q / 3;
      gp.push(v, y, -HALF, v, y, HALF, -HALF, y, v, HALF, y, v);
    }
    const ggeo = new THREE.BufferGeometry();
    ggeo.setAttribute('position', new THREE.Float32BufferAttribute(gp, 3));
    const grid = new THREE.LineSegments(ggeo,
      new THREE.LineBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.65 }));
    g.add(grid); grids.push(grid);

    const pg = new THREE.BufferGeometry();
    const pos = new Float32Array(NPTS * 3), col = new Float32Array(NPTS * 3);
    const cc = new THREE.Color();
    for (let i = 0; i < NPTS; i++) {
      pos[3 * i] = P[L][2 * i]; pos[3 * i + 1] = y; pos[3 * i + 2] = P[L][2 * i + 1];
      cc.set(cls[i] ? BLUE : RED);
      col[3 * i] = cc.r; col[3 * i + 1] = cc.g; col[3 * i + 2] = cc.b;
    }
    pg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    pg.setAttribute('color', new THREE.BufferAttribute(col, 3));
    const pm = new THREE.PointsMaterial({
      size: 5, sizeAttenuation: false, vertexColors: true,
      transparent: true, opacity: 1, depthWrite: false
    });
    const pts = new THREE.Points(pg, pm);
    pts.frustumCulled = false;
    g.add(pts); points.push(pts);
  }

  // dashed trajectories, batched per class and per inter-plane gap
  const buf = [[], []];
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) buf[c].push([]);
  for (let i = 0; i < NPTS; i++) {
    const sm = curvePoints(P, i);
    for (let s = 0; s < 6; s++) {
      pushDashes(buf[cls[i]][s], sm.slice(s * SUB, s * SUB + SUB + 1), 0.20, 0.16);
    }
  }
  const traj = [[], []];
  for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) {
    traj[c].push(segObj(g, buf[c][s], c ? BLUE : RED, 0.4));
  }

  // faint gray envelope hull linking cloud extremes plane → plane
  const env = [];
  const ext = [];
  for (let L = 0; L < NL; L++) {
    let ixMin = 0, ixMax = 0, izMin = 0, izMax = 0;
    for (let i = 1; i < NPTS; i++) {
      if (P[L][2 * i] < P[L][2 * ixMin]) ixMin = i;
      if (P[L][2 * i] > P[L][2 * ixMax]) ixMax = i;
      if (P[L][2 * i + 1] < P[L][2 * izMin + 1]) izMin = i;
      if (P[L][2 * i + 1] > P[L][2 * izMax + 1]) izMax = i;
    }
    ext.push([ixMax, izMax, ixMin, izMin].map(i =>
      new THREE.Vector3(P[L][2 * i], PLANE_Y[L], P[L][2 * i + 1])));
  }
  for (let L = 0; L < NL; L++) {
    for (let q = 0; q < 4; q++) pushDashes(env, [ext[L][q], ext[L][(q + 1) % 4]], 0.16, 0.16);
    if (L + 1 < NL) for (let q = 0; q < 4; q++) pushDashes(env, [ext[L][q], ext[L + 1][q]], 0.2, 0.18);
  }
  const envelope = segObj(g, env, 0xaaaaaa, 0.32);

  // hover highlight (pre-allocated)
  const hgeo = new THREE.BufferGeometry();
  const harr = new Float32Array(9000);
  hgeo.setAttribute('position', new THREE.BufferAttribute(harr, 3));
  hgeo.setDrawRange(0, 0);
  const hobj = new THREE.LineSegments(hgeo,
    new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 1, depthWrite: false }));
  hobj.frustumCulled = false;
  g.add(hobj);

  const dgeo = new THREE.BufferGeometry();
  dgeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(NL * 3), 3));
  const dmat = new THREE.PointsMaterial({
    size: 11, sizeAttenuation: false, color: 0x000000, transparent: true, depthWrite: false
  });
  const dots = new THREE.Points(dgeo, dmat);
  dots.frustumCulled = false;
  dots.visible = false;
  g.add(dots);

  return { k, P, group: g, borders, thicks, grids, points, traj, envelope, hobj, harr, hgeo, dots, dgeo, dmat };
}

const columns = [];
for (let k = 0; k < NCOL; k++) columns.push(buildColumn(k));

/* ── legend column: 7 arrows (boxed labels are HTML, added below) ──────────── */
const blackMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
const legendBase = U.clone().multiplyScalar(LEG_X);
for (let k = 0; k < NL; k++) {
  const y = PLANE_Y[k];
  const a = legendBase.clone().setY(y - 1.15);
  const b = legendBase.clone().setY(y + 0.85);
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), blackLine));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.55, 12), blackMat);
  head.position.copy(legendBase).setY(y + 1.1);
  root.add(head);
}

/* ── training-iteration axis with two ellipsis breaks + arrow head ────────── */
const ELL_F = [1.5 * SPACING, 2.5 * SPACING];
const breaks = [
  [AX_START, ELL_F[0] - 1.5],
  [ELL_F[0] + 1.5, ELL_F[1] - 1.5],
  [ELL_F[1] + 1.5, AX_END]
];
for (const [f0, f1] of breaks) {
  root.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([alongU(f0, AXIS_Y), alongU(f1, AXIS_Y)]), blackLine));
}
const axisHead = new THREE.Mesh(new THREE.ConeGeometry(0.26, 0.8, 12), blackMat);
axisHead.position.copy(alongU(AX_END + 0.4, AXIS_Y));
axisHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), U);
root.add(axisHead);

/* ── invisible bounding-box padding so HTML labels stay inside the frame ──── */
const padPts = [
  alongU(AX_START - 5.5, AXIS_Y),
  alongU(LEG_X - 2.5, PLANE_Y[NL - 1] + 1.6),
  alongU(AX_END + 1.5, AXIS_Y)
];
const padGeo = new THREE.BufferGeometry().setFromPoints(padPts);
const pad = new THREE.Points(padGeo,
  new THREE.PointsMaterial({ size: 0.001, transparent: true, opacity: 0, depthWrite: false }));
pad.frustumCulled = false;
root.add(pad);

/* ── camera: frame the whole four-column composition ──────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.9
});
controls.minPolarAngle = THREE.MathUtils.degToRad(25);
controls.maxPolarAngle = THREE.MathUtils.degToRad(82);
controls.minAzimuthAngle = THREE.MathUtils.degToRad(5);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(85);

/* ── labels ───────────────────────────────────────────────────────────────── */
const boxCSS = 'display:inline-block;border:1.3px solid #1a1a1a;border-radius:10px;padding:3px 10px;' +
  'background:#fff;font-family:ui-monospace,Consolas,monospace;font-size:15px;color:#111;line-height:1.1;';
for (let k = 0; k < 6; k++) {
  addLabel(`<span style="${boxCSS}">${LEGEND[k]}</span>`,
    world(legendBase.clone().setY(PLANE_Y[k] + GAP / 2)));
}
addLabel('Training iteration', world(alongU(AX_START - 3.0, AXIS_Y)), { fontSize: '15px' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', world(alongU(ELL_F[0], AXIS_Y)), { fontSize: '19px' });
addLabel('&middot;&nbsp;&middot;&nbsp;&middot;', world(alongU(ELL_F[1], AXIS_Y)), { fontSize: '19px' });

const iterLabel = addLabel('iteration 0', world(alongU(0, CAP_Y)),
  { fontSize: '12px', color: '#1565c0', bold: true });

/* ── style / highlight state ──────────────────────────────────────────────── */
let focusIter = 0;
let activeLayer = -1;          // -1 = every layer shown
let compareAll = true;
let hoverIdx = -1;

function applyStyle() {
  for (let k = 0; k < NCOL; k++) {
    const col = columns[k];
    const focused = compareAll || k === focusIter;
    const base = focused ? 1 : 0.14;
    for (let L = 0; L < NL; L++) {
      const A = activeLayer;
      const above = A >= 0 && L > A;
      const isA = A >= 0 && L === A;
      col.borders[L].material.color.set(isA ? 0x000000 : 0x444444);
      col.borders[L].material.opacity = base * (above ? 0.2 : 0.92);
      col.thicks[L].visible = isA && focused;
      col.grids[L].material.opacity = base * (above ? 0.1 : 0.65);
      let po = 1;
      if (A >= 0) po = (L === A || L === A - 1) ? 1 : (above ? 0.1 : 0.35);
      col.points[L].material.opacity = base * po;
    }
    for (let c = 0; c < 2; c++) for (let s = 0; s < 6; s++) {
      const o = activeLayer < 0 ? 0.4 : (s === activeLayer - 1 ? 0.95 : 0.06);
      col.traj[c][s].material.opacity = base * o;
    }
    col.envelope.material.opacity = base * (activeLayer < 0 ? 0.32 : 0.1);
  }
  iterLabel.pos.copy(world(alongU(focusIter * SPACING, CAP_Y)));
  iterLabel.div.textContent = `iteration ${focusIter}`;
  iterLabel.div.style.opacity = compareAll ? '0.75' : '1';
}

/* ── hover trace: same datapoint highlighted in all four columns ──────────── */
function refreshTrace() {
  for (const col of columns) {
    if (hoverIdx < 0) { col.hgeo.setDrawRange(0, 0); col.dots.visible = false; continue; }
    const out = [];
    pushDashes(out, curvePoints(col.P, hoverIdx), 0.26, 0.12);
    const n = Math.min(out.length, col.harr.length);
    for (let i = 0; i < n; i++) col.harr[i] = out[i];
    col.hgeo.attributes.position.needsUpdate = true;
    col.hgeo.setDrawRange(0, n / 3);
    col.hobj.material.color.set(cls[hoverIdx] ? BLUE : RED);
    const arr = col.dgeo.attributes.position.array;
    for (let L = 0; L < NL; L++) {
      arr[3 * L] = col.P[L][2 * hoverIdx];
      arr[3 * L + 1] = PLANE_Y[L];
      arr[3 * L + 2] = col.P[L][2 * hoverIdx + 1];
    }
    col.dgeo.attributes.position.needsUpdate = true;
    col.dmat.color.set(cls[hoverIdx] ? BLUE : RED);
    col.dots.visible = true;
  }
}

/* ── UI wiring ────────────────────────────────────────────────────────────── */
const iterNames = ['initialization', 'early training', 'mid training', 'late training'];
const slider = document.getElementById('iterSlider');
const readout = document.getElementById('iterReadout');

function setIteration(t, fromSlider) {
  focusIter = Math.max(0, Math.min(3, t | 0));
  readout.innerHTML = `iteration ${focusIter} / 3 &nbsp;(${iterNames[focusIter]})`;
  if (!fromSlider) slider.value = String(focusIter);
  applyStyle();
}
slider.addEventListener('input', () => setIteration(parseInt(slider.value, 10), true));

const chkCompare = document.getElementById('chkCompare');
chkCompare.addEventListener('change', () => { compareAll = chkCompare.checked; applyStyle(); });

const layerBtns = document.getElementById('layerBtns');
const btnDefs = ['all layers'].concat(LAYER_NAMES);
btnDefs.forEach((n, i) => {
  const b = document.createElement('button');
  b.textContent = n;
  b.style.fontFamily = 'ui-monospace,Consolas,monospace';
  b.style.fontSize = '11px';
  b.addEventListener('click', () => setLayer(i - 1));
  layerBtns.appendChild(b);
});
function setLayer(idx) {
  activeLayer = idx;
  [...layerBtns.children].forEach((b, i) => b.classList.toggle('active', i - 1 === idx));
  applyStyle();
}

let playTimer = null;
const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play training';
    return;
  }
  compareAll = false; chkCompare.checked = false;
  setIteration(0, false);
  btnPlay.textContent = '❚❚ Pause';
  playTimer = setInterval(() => { setIteration((focusIter + 1) % 4, false); }, 1200);
});

const STEPS = [
  {
    title: 'Initialization: classes intermingled',
    narr: 'At iteration 0 red and blue stay mixed all the way up the stack; even the softmax plane shows the two colours overlapping in one clump.',
    t: 0, layer: 6
  },
  {
    title: 'Start at the input plane',
    narr: 'The bottom plane holds the raw data: one dense central cluster with red and blue thoroughly intermingled. It is identical in all four columns.',
    t: 0, layer: 0
  },
  {
    title: 'First linear + relu',
    narr: 'The first linear layer rotates and shrinks the cloud; relu then folds everything lying past the axes back toward them, producing the first hint of structure.',
    t: 2, layer: 2
  },
  {
    title: 'Deeper layers pull the classes apart',
    narr: 'By the second relu the red points have collected into a narrow bundle while the blue points bow outward to one side of the plane.',
    t: 2, layer: 4
  },
  {
    title: 'Late training, full forward pass',
    narr: 'In the rightmost column the softmax plane shows a tight red thread near the centre and blue points flung far past the plane edge — a clean, confident separation.',
    t: 3, layer: 6
  }
];
let stepIdx = -1;
function goToStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play training'; }
  setIteration(s.t, false);
  setLayer(s.layer);
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length}  ${s.title}`;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));

setLayer(-1);
setIteration(0, false);

/* ── pointer picking on the point clouds ──────────────────────────────────── */
const allPoints = [];
for (const col of columns) for (const p of col.points) allPoints.push(p);
const myRay = new THREE.Raycaster();
myRay.params.Points.threshold = 0.05;
const myPointer = new THREE.Vector2();

function pickIndex(event) {
  const rect = canvas.getBoundingClientRect();
  myPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  myPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  myRay.setFromCamera(myPointer, camera);
  const hits = myRay.intersectObjects(allPoints, false);
  return hits.length ? hits[0].index : -1;
}
function pointInfo(i) {
  const P = columns[focusIter].P;
  const f = (L) => `(${P[L][2 * i].toFixed(2)}, ${P[L][2 * i + 1].toFixed(2)})`;
  return `${cls[i] ? 'blue' : 'red'} datapoint #${i} @ iteration ${focusIter} · ` +
    `input ${f(0)} → relu1 ${f(2)} → relu2 ${f(4)} → softmax ${f(6)}`;
}
canvas.addEventListener('pointermove', (e) => {
  const idx = pickIndex(e);
  if (idx !== hoverIdx) { hoverIdx = idx; refreshTrace(); }
  if (idx >= 0) showTooltip(pointInfo(idx), e);
});
canvas.addEventListener('pointerleave', () => {
  if (hoverIdx !== -1) { hoverIdx = -1; refreshTrace(); }
});
canvas.addEventListener('click', (e) => {
  const idx = pickIndex(e);
  if (idx < 0) return;
  showPopup(`${cls[idx] ? 'Blue' : 'Red'} datapoint #${idx}`,
    'This single datapoint keeps its identity through all seven activation planes, and it appears in ' +
    'every training column. Its dashed trajectory shows where each linear, relu and softmax layer ' +
    'sends it; comparing columns shows how training reshapes that path. ' + pointInfo(idx));
});
